3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.internal.SharedConstants;
8	import org.jsoup.internal.StringUtil;
9	import org.jsoup.parser.Tag;
10	import org.jsoup.select.Elements;
11	import org.jsoup.select.Evaluator;
12	import org.jsoup.select.Selector;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.ArrayList;
16	import java.util.List;
17	
18	/**
19	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
20	 * form to easily be submitted.
21	 */
22	public class FormElement extends Element {
23	    private final Elements linkedEls = new Elements();
24	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
25	    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));
26	
27	    /**
28	     * Create a new, standalone form element.
29	     *
30	     * @param tag        tag of this element
31	     * @param baseUri    the base URI
32	     * @param attributes initial attributes
33	     */
34	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
35	        super(tag, baseUri, attributes);
36	    }
37	
38	    /**
39	     * Get the list of form control elements associated with this form.
40	     * @return form controls associated with this element.
41	     */
42	    public Elements elements() {
43	        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
44	        Elements els = select(submittable); // current form children
45	        for (Element linkedEl : linkedEls) {
46	            if (linkedEl.ownerDocument() != null && !els.contains(linkedEl)) {
47	                els.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
48	            }
49	        }
50	
51	        return els;
52	    }
53	
54	    /**
55	     * Add a form control element to this form.
56	     * @param element form control to add
57	     * @return this form element, for chaining
58	     */
59	    public FormElement addElement(Element element) {
60	        linkedEls.add(element);
61	        return this;
62	    }
63	
64	    @Override
65	    protected void removeChild(Node out) {
66	        super.removeChild(out);
67	        linkedEls.remove(out);
68	    }
69	
70	    /**
71	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
72	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
73	     (if any), as available in {@link Document#connection()}
74	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
75	
76	     @return a connection prepared from the values of this form, in the same session as the one used to request it
77	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
78	     document's base URI when parsing.
79	     */
80	    public Connection submit() {
81	        String action = hasAttr("action") ? absUrl("action") : baseUri();
82	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
83	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
84	                Connection.Method.POST : Connection.Method.GET;
85	
86	        Document owner = ownerDocument();
87	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
88	        return connection.url(action)
89	                .data(formData())
90	                .method(method);
91	    }
92	
93	    /**
94	     * Get the data that this form submits, using the browser's <i>successful controls</i> semantics: controls are
95	     * returned in DOM order; controls without a {@code name}, disabled controls (including those inside a disabled
96	     * {@code fieldset}), and {@code button} / {@code reset} / {@code submit} / {@code image} inputs are excluded;
97	     * checkboxes and radios are only included when {@code checked} (defaulting to the value {@code "on"}); a
98	     * {@code select[multiple]} submits every selected option, while a single {@code select} with no selected option
99	     * falls back to its first non-disabled option. The list is re-queried from the DOM on each call, so changes to
100	     * the document are reflected. The returned list is a copy of the data, and changes to the contents of the
101	     * list will not be reflected in the DOM.
102	     * @return a list of key vals
103	     */
104	    public List<Connection.KeyVal> formData() {
105	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
106	
107	        // iterate the form control elements and accumulate their values
108	        Elements formEls = elements();
109	        for (Element el: formEls) {
110	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
111	            if (isDisabled(el)) continue; // skip disabled form inputs
112	            String name = el.attr("name");
113	            if (name.length() == 0) continue;
114	            String type = el.attr("type");
115	
116	            if (el.nameIs("button") || type.equalsIgnoreCase("button") || type.equalsIgnoreCase("reset")
117	                || type.equalsIgnoreCase("submit") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these (a submit button only if it was the clicker)
118	
119	            if (el.nameIs("select")) {
120	                Elements options = el.select("option[selected]");
121	                boolean set = false;
122	                for (Element option: options) {
123	                    if (option.hasAttr("disabled")) continue; // disabled options are not successful
124	                    data.add(HttpConnection.KeyVal.create(name, option.val()));
125	                    set = true;
126	                }
127	                if (!set && !el.hasAttr("multiple")) {
128	                    // a single select defaults to its first non-disabled option
129	                    for (Element option : el.select("option")) {
130	                        if (!option.hasAttr("disabled")) {
131	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
132	                            break;
133	                        }
134	                    }
135	                }
136	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
137	                // only add checkbox or radio if they have the checked attribute
138	                if (el.hasAttr("checked")) {
139	                    final String val = el.val().length() >  0 ? el.val() : "on";
140	                    data.add(HttpConnection.KeyVal.create(name, val));
141	                }
142	            } else {
143	                data.add(HttpConnection.KeyVal.create(name, el.val()));
144	            }
145	        }
146	        return data;
147	    }
148	
149	    /**
150	     * A form control is disabled if it has the {@code disabled} attribute, or if it is a descendant of a
151	     * {@code fieldset} that does.
152	     */
153	    private static boolean isDisabled(Element el) {
154	        for (Element parent = el; parent != null; parent = parent.parent()) {
155	            if (parent.hasAttr("disabled") && (parent == el || parent.nameIs("fieldset")))
156	                return true;
157	        }
158	        return false;
159	    }
160	
161	    @Override
162	    public FormElement clone() {
163	        return (FormElement) super.clone();
164	    }
165	}
